// Cowork release bundle — assembles the MECHANICAL parts of the 5-part bundle (see the Standing Sync Protocol in the
// shared Drive folder). Run this at every version bump, then CC (Claude) adds the two human/AI-authored parts and
// pushes the whole folder to the shared Drive folder.
//
//   node scripts/build-release-bundle.mjs [version]      e.g. `node scripts/build-release-bundle.mjs v3.2.1`
//
// Produces  dist/cowork-bundle/  containing:
//   1. member-transcript.md        — clean authored copy, reading order (build-transcript.mjs)   [QUOTE FROM THIS]
//   2. member-facing-strings.txt   — full raw string dump (extract-member-strings.mjs)           [traceability backstop]
//   5. voice-rules.md              — the canonical voice/brand doc (governs the DYNAMIC copy)     [describe-dynamic]
//   MANIFEST.md                    — stamped version · commit · date + the checklist for CC's two remaining parts.
//
// CC then adds, before pushing to Drive:
//   3. sync-note (Marketing Alignment Brief format) — what changed in voice / naming / story / function.
//   4. screenshots of key surfaces (via the preview tools).
// The Drive push itself is done by CC via the Drive connector (can't run headless from this script).

import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = process.cwd();
const version = process.argv[2] || 'unstamped';
const OUT = join(ROOT, 'dist/cowork-bundle');
mkdirSync(OUT, { recursive: true });

let commit = 'unknown';
try { commit = execSync('git rev-parse --short HEAD', { cwd: ROOT }).toString().trim(); } catch {}
const date = new Date().toISOString().slice(0, 10);

// 1 + 2 — the two extractors (they write to docs/, then we copy into the bundle).
execSync('node scripts/build-transcript.mjs', { cwd: ROOT, stdio: 'inherit' });
execSync('node scripts/extract-member-strings.mjs', { cwd: ROOT, stdio: 'inherit' });
copyFileSync(join(ROOT, 'docs/member-transcript.md'), join(OUT, 'member-transcript.md'));
copyFileSync(join(ROOT, 'docs/member-facing-strings.txt'), join(OUT, 'member-facing-strings.txt'));

// 5 — voice rules: the canonical brand/voice doc governs the dynamic (model-generated) Companion copy.
copyFileSync(join(ROOT, 'docs/brand-ui-standards.md'), join(OUT, 'voice-rules.md'));

const transcriptCount = (readFileSync(join(OUT, 'member-transcript.md'), 'utf8').match(/^- /gm) || []).length;

const manifest = `# Cowork Release Bundle — ${version}

**Stamp:** \`${version} · app @ ${commit} · ${date}\`
**Reconciles against glossary:** _(fill in the glossary version Cowork reconciled to)_

Per the Standing Sync Protocol (shared Drive folder). CC drops this at every version bump; Cowork reconciles it into the glossary on the morning scan; Jay only decides.

## The 5 parts
1. \`member-transcript.md\` — clean authored copy, reading order (${transcriptCount} strings). **QUOTE FROM THIS.**
2. \`member-facing-strings.txt\` — full raw dump, traceability backstop. **Do NOT quote** (may contain system/model-instruction strings).
3. \`sync-note.md\` — _CC adds:_ the Marketing Alignment Brief (what changed in voice / naming / story / function).
4. \`screenshots/\` — _CC adds:_ key surfaces (dashboard, a session, badges, a ceremony).
5. \`voice-rules.md\` — the canonical voice/brand doc that governs the DYNAMIC (model-generated) Companion copy. **Describe-dynamic**, don't quote.

## Quotability rule (critical for the book)
- Authored copy (transcript, assessment items, UI, badges) is fixed → **quote verbatim**.
- The Companion's in-the-moment reflections are model-generated and vary per member → **never quote as canonical; describe by the voice rules**.

Generated by \`scripts/build-release-bundle.mjs\`. To regenerate for a new version: bump prod, then \`node scripts/build-release-bundle.mjs <version>\`.
`;
writeFileSync(join(OUT, 'MANIFEST.md'), manifest);

console.log(`\nBundle assembled → dist/cowork-bundle/  (${version} · ${commit} · ${date})`);
console.log('Mechanical parts done (1, 2, 5, MANIFEST). CC still adds: 3 sync-note, 4 screenshots — then push the folder to the shared Drive folder.');
